-- V1: the customers table.
-- Flyway runs this file once, in order, and records it in flyway_schema_history.
-- Never edit a file after it has run anywhere: Flyway stores a checksum and refuses to start
-- if it changed. To change the schema, add V2__..., V3__... instead.

CREATE TABLE customers (
    -- UUID generated by the app (Customer.create), so ids can't be guessed or counted.
    id          UUID          PRIMARY KEY,
    -- Which merchant (tenant) owns this customer. Temporary: comes from the request until L2.
    tenant_id   UUID          NOT NULL,
    name        VARCHAR(200)  NOT NULL,
    -- 320 = the maximum length of a valid email address.
    email       VARCHAR(320)  NOT NULL,
    -- TIMESTAMPTZ stores an exact moment (with time zone), so servers in any zone agree.
    created_at  TIMESTAMPTZ   NOT NULL,

    -- Two merchants may each have a customer with the same email, but one merchant may not
    -- have it twice. The DATABASE enforces this, so it also wins a race between two
    -- simultaneous requests (a Java "does it exist?" check alone can't).
    CONSTRAINT uq_customers_tenant_email UNIQUE (tenant_id, email)
);
